from dataclasses import dataclass

@dataclass
class Const:
    value: float
@dataclass
class Var:
    index: int
@dataclass
class Add:
    left: 'Circuit'
    right: 'Circuit'
@dataclass
class Mul:
    left: 'Circuit'
    right: 'Circuit'
Circuit = Const | Var | Add | Mul

def evaluate(c, v):
    match c:
        case Const(value=val): return val
        case Var(index=i): return v[i]
        case Add(left=l, right=r): return evaluate(l, v) + evaluate(r, v)
        case Mul(left=l, right=r): return evaluate(l, v) * evaluate(r, v)

x, y = Var(0), Var(1)
c_expanded = Add(Add(Mul(x, x), Mul(Const(2.0), Mul(x, y))), Mul(y, y))
c_factored = Mul(Add(x, y), Add(x, y))

for xv, yv in [(1,2), (3,-1), (0.5,0.7)]:
    v1 = evaluate(c_expanded, [xv, yv])
    v2 = evaluate(c_factored, [xv, yv])
    poly = xv**2 + 2*xv*yv + yv**2
    print(f'({xv},{yv}): expanded={v1}, factored={v2}, poly={poly}, match={abs(v1-poly)<1e-10}')

